//! `schema/commands.v1.json`: every command of the app with its title key, leader group,
//! default bindings and MCP mapping, as the window registers them ([`super::register_all`]).
//! Generated by a test (`RB_UPDATE_SCHEMA=1`), never edited by hand; the wiki's keyboard
//! reference (`scripts/keyboard-reference.sh`) is rendered from it (RB-010-17).

use rb_commands::{CommandRegistry, Group, LEADER};
use serde_json::{Value, json};

/// The checked-in file, relative to the repository root.
pub const COMMANDS_FILE: &str = "schema/commands.v1.json";

/// The document for `registry`: the leader, the groups in the docs' order and the commands in
/// the groups' order, by id inside a group; pretty JSON with a trailing newline.
pub fn commands_document(registry: &CommandRegistry) -> String {
    let groups: Vec<Value> = Group::ALL
        .iter()
        .map(|group| {
            json!({
                "id": group.id(),
                "key": group.leader_key().to_string(),
                "titleKey": group.title_key(),
            })
        })
        .collect();
    let mut summaries = registry.summaries();
    summaries.sort_by(|a, b| (a.group, a.id.as_str()).cmp(&(b.group, b.id.as_str())));
    let commands: Vec<Value> = summaries
        .into_iter()
        .map(|summary| {
            json!({
                "id": summary.id.as_str(),
                "titleKey": summary.title_key,
                "group": summary.group.id(),
                "defaultBindings": summary.default_bindings,
                "mcp": summary.mcp,
            })
        })
        .collect();
    let document = json!({
        "$comment": "Generated from the command registry by \
                     `RB_UPDATE_SCHEMA=1 cargo nextest run -p rbrowser commands_file`; \
                     do not edit by hand.",
        "version": 1,
        "leader": LEADER.to_string(),
        "groups": groups,
        "commands": commands,
    });
    let mut text = serde_json::to_string_pretty(&document).expect("a JSON value always serializes");
    text.push('\n');
    text
}

